        { question: 'HLV संरक्षणासाठी कोणती एलआयसी पॉलिसी उत्तम आहे?', answer: 'प्युअर टर्म इन्शुरन्स जसे एलआयसी टेक टर्म (Plan 855) कमी हप्त्यात मोठा विमा मिळवण्यासाठी सर्वोत्तम आहे.' },
        { question: 'वय वाढल्यावर HLV कमी होते का?', answer: 'होय, निवृत्ती जवळ आल्यावर कामाची वर्षे कमी झाल्याने आणि संपत्ती वाढल्याने HLV ची गरज कमी होते.' }
