      metaDescription: 'તમારી LIC પોલિસીનું સરન્ડર મૂલ્ય ઓનલાઇન તપાસો. ગેરંટીયુક્ત સરન્ડર વેલ્યુ (GSV) અને સ્પેશિયલ સરન્ડર વેલ્યુ (SSV).',
