        { question: 'হোম লোন কি HLV তে যোগ করা উচিত?', answer: 'হ্যাঁ, কোনো অপ্রত্যাশিত ঘটনায় পরিবারের ওপর ঋণের বোঝা যাতে না পড়ে, তাই সমস্ত ঋণ HLV কভারে যোগ করা হয়।' },
        { question: 'HLV কভার করতে কোন এলআইসি পলিসি সেরা?', answer: 'পিওর টার্ম ইন্স্যুরেন্স যেমন এলআইসি টেক টার্ম (Plan 855) কম খরচে বড় কভার পাওয়ার জন্য সেরা।' },
        { question: 'বয়স বাড়ার সাথে সাথে কি HLV কমে?', answer: 'হ্যাঁ, অবসর কাছাকাছি এলে উপার্জনের বাকি বছর কমে যাওয়া এবং সঞ্চয় বৃদ্ধি পাওয়ায় প্রয়োজনীয় HLV হ্রাস পায়।' }
